import test from 'node:test';
import assert from 'node:assert/strict';
import { rotate } from '../src/rotate.js';

const cases = [
  { name: 'four elements by one step', input: [1, 2, 3, 4], steps: 1, expected: [4, 1, 2, 3] },
  { name: 'four elements by two steps', input: [1, 2, 3, 4], steps: 2, expected: [3, 4, 1, 2] },
  { name: 'zero steps', input: [1, 2, 3, 4], steps: 0, expected: [1, 2, 3, 4] },
  { name: 'one full turn', input: [1, 2, 3, 4], steps: 4, expected: [1, 2, 3, 4] },
  { name: 'steps exceeding the length', input: [1, 2, 3, 4], steps: 6, expected: [3, 4, 1, 2] },
  { name: 'singleton at zero steps', input: ['only'], steps: 0, expected: ['only'] },
  { name: 'singleton at positive steps', input: ['only'], steps: 7, expected: ['only'] },
  { name: 'empty array at zero steps', input: [], steps: 0, expected: [] },
  { name: 'empty array at positive steps', input: [], steps: 7, expected: [] },
  { name: 'repeated values preserve order', input: ['a', 'b', 'a', 'c', 'b'], steps: 2, expected: ['c', 'b', 'a', 'b', 'a'] },
];

for (const { name, input, steps, expected } of cases) {
  test(`rotate: ${name}`, () => {
    const original = [...input];
    const result = rotate(input, steps);

    assert.ok(Array.isArray(result));
    assert.notStrictEqual(result, input, 'must return a new array');
    assert.deepStrictEqual(result, expected);
    assert.deepStrictEqual(input, original, 'must preserve input contents');

    result.push('result-only marker');
    assert.deepStrictEqual(input, original, 'changing the result must not change the input array');
  });
}

const nonArrays = [
  { name: 'undefined', value: undefined },
  { name: 'null', value: null },
  { name: 'number', value: 42 },
  { name: 'boolean', value: false },
  { name: 'string', value: 'abcd' },
  { name: 'plain object', value: {} },
  { name: 'array-like object', value: { 0: 'a', length: 1 } },
  { name: 'typed array', value: new Uint8Array([1, 2]) },
];

for (const { name, value } of nonArrays) {
  test(`rotate rejects non-array ${name}`, () => {
    assert.throws(() => rotate(value, 1), TypeError);
  });
}

for (const steps of [-1, -4, 0.5, 1.5, -0.5]) {
  test(`rotate rejects invalid steps ${steps} without changing a populated array`, () => {
    const input = [1, 2, 3, 4];
    assert.throws(() => rotate(input, steps), RangeError);
    assert.deepStrictEqual(input, [1, 2, 3, 4]);
  });

  test(`rotate rejects invalid steps ${steps} for an empty array`, () => {
    const input = [];
    assert.throws(() => rotate(input, steps), RangeError);
    assert.deepStrictEqual(input, []);
  });
}

